 {page === 'add' && <><button className="back-link" onClick={() => navigate(draft.id ? 'detail' : 'items', draft.id)}><ArrowLeft size={17}/>Back</button><div className="page-heading"><div><span className="eyebrow">ONE LESS THING TO REMEMBER</span><h1>{draft.id ? 'Edit responsibility' : 'What’s on your mind?'}</h1><p>Just the essentials to start. You can add more anytime.</p></div></div><form className="panel form-panel" onSubmit={save}><Field label="What would you like to remember?"><input autoFocus required maxLength={160} placeholder="e.g. Renew car insurance" value={draft.title} onChange={e => setDraft({ ...draft, title: e.target.value })}/></Field><div className="form-grid"><Field label="Category"><Picker label="Category" value={draft.category} onChange={category => setDraft({ ...draft, category })} options={[...categories]}/></Field><Field label="Due or expiration date" hint="Not sure? Leave it blank until you can confirm."><input type="date" value={draft.due} onChange={e => setDraft({ ...draft, due: e.target.value })}/></Field></div><div className="form-grid"><Field label="Repeat"><Picker label="Repeat" value={draft.recurrence} onChange={recurrence => setDraft({ ...draft, recurrence })} options={[['none', 'One time'], ['weekly', 'Weekly'], ['monthly', 'Monthly'], ['annual', 'Annually'], ['daily', 'Custom · days']]}/></Field>{draft.recurrence !== 'none' && <Field label="Every" hint={`Number of ${draft.recurrence === 'annual' ? 'years' : draft.recurrence === 'monthly' ? 'months' : draft.recurrence === 'weekly' ? 'weeks' : 'days'}`}><input required type="number" min={1} max={999} value={draft.interval} onChange={e => setDraft({ ...draft, interval: Number(e.target.value) })}/></Field>}</div>{draft.recurrence !== 'none' && <Field label="Schedule the next cycle from"><Picker label="Recurrence basis" value={draft.basis} onChange={basis => setDraft({ ...draft, basis })} options={[['calendar', 'The scheduled date'], ['completion', 'The date I complete it']]}/></Field>}
 <Field label="Remind me before the deadline" hint="Choose the schedule you want. Passed reminders are combined into the most relevant next step."><div className="reminder-pills">{[45, 30, 14, 7, 1, 0].map(n => <label key={n} className={draft.reminders.includes(n) ? 'chosen' : ''}><Checkbox checked={draft.reminders.includes(n)} onCheckedChange={v => setDraft({ ...draft, reminders: v ? [...draft.reminders, n] : draft.reminders.filter(x => x !== n) })}/>{n === 0 ? 'On the day' : `${n} days`}</label>)}</div></Field><details className="more-details"><summary>More details <Plus size={17}/></summary><div className="form-grid"><Field label="Person, pet, vehicle, or property"><input placeholder="e.g. My car, Luna, or our home" value={draft.associated} maxLength={200} onChange={e => setDraft({ ...draft, associated: e.target.value })}/></Field><Field label="Provider or organization"><input value={draft.provider} maxLength={200} onChange={e => setDraft({ ...draft, provider: e.target.value })}/></Field><Field label="Cost"><input inputMode="decimal" placeholder="0.00" value={draft.cost} onChange={e => setDraft({ ...draft, cost: e.target.value })}/></Field><Field label="Currency"><input maxLength={3} value={draft.currency} onChange={e => setDraft({ ...draft, currency: e.target.value.toUpperCase() })}/></Field></div><Field label="Notes"><textarea rows={4} maxLength={10000} placeholder="Anything that will make this easier next time…" value={draft.notes} onChange={e => setDraft({ ...draft, notes: e.target.value })}/></Field></details>{attached && <p className="info-note"><FileText size={17}/>Your uploaded document will be attached after saving.</p>}<div className="form-footer"><span><ShieldCheck size={16}/>Only visible to you</span><button className="btn primary" disabled={busy || offline}>{busy ? <LoaderCircle className="spin" size={18}/> : <Check size={18}/>} {draft.id ? 'Save changes' : 'Add responsibility'}</button></div></form></>}
 {page === 'detail' && item && <><button className="back-link" onClick={() => navigate('items')}><ArrowLeft size={17}/>All responsibilities</button><div className="page-heading"><div><span className="eyebrow">{item.category}</span><h1>{item.title}</h1><p>{item.associated}{item.associated && item.provider ? ' · ' : ''}{item.provider}</p></div><span className={'status large ' + (status(item, date) === 'Overdue' ? 'danger' : '')}>{status(item, date)}</span></div><div className="detail-grid"><div><section className="panel detail-summary"><span className="eyebrow">YOUR NEXT DEADLINE</span><h2>{item.due ? new Date(item.due + 'T12:00:00').toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }) : 'No date set yet'}</h2><p>{dueLabel(item, date)}</p><div className="detail-meta"><span><RefreshCw size={17}/>{item.recurrence === 'none' ? 'One time' : `Every ${item.interval} ${item.recurrence === 'annual' ? 'year(s)' : item.recurrence === 'monthly' ? 'month(s)' : item.recurrence === 'weekly' ? 'week(s)' : 'day(s)'}`}</span>{item.cost && <span>{item.currency} {Number(item.cost).toFixed(2)}</span>}</div><div className="action-row">{item.status === 'active' && <button className="btn primary" onClick={() => { setCompleteNotes(''); setConfirmedDate(nextDate(item, date)); setCompleteOpen(true); }}><Check size={18}/>Mark complete</button>}<button className="btn secondary" onClick={() => { setDraft({ ...item }); setAttached(''); navigate('add'); }}>Edit / reschedule</button>{item.status === 'active' && <button className="btn secondary" onClick={() => { setSnoozeDate(shift(date, 1)); setSnoozeOpen(true); }}><Clock size={17}/>Snooze</button>}</div>{item.snooze && item.snooze > date && <p className="info-note">Reminders snoozed until {item.snooze}.</p>}</section>
 <section className="panel checklist-panel"><div className="section-heading"><h2>Help me handle this</h2><span className="muted text-sm">Your preparation checklist</span></div>{!item.checklist.length && <div className="suggested-guidance"><p>Suggested steps to make this easier. Confirm details against your own records.</p>{guidance(item.category).map((g, j) => <p key={g}><span>{j + 1}</span>{g}</p>)}<button className="btn secondary" disabled={busy} onClick={() => run(async () => { await api({ action: 'save', item: { ...item, checklist: guidance(item.category).map(text => ({ text, done: false })) } }); await reload(); })}>Use this checklist <Plus size={17}/></button></div>}{item.checklist.map((c, j) => <div className="checklist-row" key={j}><Checkbox aria-label={c.text} checked={c.done} disabled={busy} onCheckedChange={v => run(async () => { await api({ action: 'save', item: { ...item, checklist: item.checklist.map((x, k) => k === j ? { ...x, done: !!v } : x) } }); await reload(); })}/><input aria-label="Checklist step" className={c.done ? 'done' : ''} defaultValue={c.text} key={c.text} maxLength={500} onBlur={e => { const text = e.target.value.trim(); if (text && text !== c.text)
                run(async () => { await api({ action: 'save', item: { ...item, checklist: item.checklist.map((x, k) => k === j ? { ...x, text } : x) } }); await reload(); }); }}/><button className="icon-button" aria-label="Remove checklist step" onClick={() => run(async () => { await api({ action: 'save', item: { ...item, checklist: item.checklist.filter((_, k) => k !== j) } }); await reload(); })}><X size={16}/></button></div>)}<form className="inline-form" onSubmit={e => { e.preventDefault(); if (checkText.trim())
                run(async () => { await api({ action: 'save', item: { ...item, checklist: [...item.checklist, { text: checkText.trim(), done: false }] } }); setCheckText(''); await reload(); }); }}><input aria-label="Add a checklist step" placeholder="Add a step…" value={checkText} maxLength={500} onChange={e => setCheckText(e.target.value)}/><button className="btn secondary" disabled={busy}><Plus size={17}/>Add</button></form></section>
 {item.notes && <section className="panel padded"><h2>Notes</h2><p className="prewrap">{item.notes}</p></section>}<section className="panel padded"><div className="section-heading"><h2>Supporting documents</h2>{uploadControl}</div>{data?.documents.filter(d => d.item === item.id).map(doc => <div className="document-row" key={doc.id}><FileText size={22}/><a href={'/api/documents?id=' + doc.id}>{doc.name}</a><span>{Math.ceil(doc.size / 1024)} KB</span><button className="icon-button" aria-label={'Delete ' + doc.name} onClick={() => setConfirm({ kind: 'document', id: doc.id, name: doc.name })}><Trash2 size={17}/></button></div>)}{!data?.documents.some(d => d.item === item.id) && <p className="muted">Keep policies, receipts, and replacement records here.</p>}</section></div>
 <aside><section className="panel padded"><h2>Reminder timeline</h2>{[...item.reminders].sort((a, b) => b - a).map(n => <div className="timeline-step" key={n}><span><Bell size={15}/></span><div><strong>{n === 0 ? 'On the due date' : `${n} days before`}</strong><p>{item.due ? shift(item.due, -n) : 'Waiting for a due date'}</p></div></div>)}{!item.reminders.length && <p className="muted">No reminders selected.</p>}<small className="muted">Times follow {data?.profile.timezone}. Passed stages are combined. Snoozing keeps your due date unchanged.</small></section><section className="panel padded"><h2>Completion history</h2>{history.filter(h => h.item === item.id).map(h => <div className="completion-record" key={h.id}><CheckCircle2 size={19}/><div><strong>{new Date(h.completed).toLocaleDateString()}</strong><p>{h.notes || 'Completed'}</p><small>{h.nextDate ? 'Next date: ' + h.nextDate : 'One-time responsibility completed'}</small></div></div>)}{!history.some(h => h.item === item.id) && <p className="muted">Each completed cycle will appear here.</p>}</section><button className="btn text-button" onClick={() => setConfirm({ kind: 'archive', name: item.title })}><Archive size={17}/>{item.status === 'archived' ? 'Restore responsibility' : 'Archive responsibility'}</button></aside></div></>}
